arguments.command:
python3 -c "
import json
with open('/app/resources/treasury_bulletin_2020_12.json') as f:
    data = json.load(f)

# Search for unemployment insurance keys
def find_keys(d, path=''):
    if isinstance(d, dict):
        for k, v in d.items():
            if 'unemployment' in k.lower():
                print(f'{path}->{k}')
            find_keys(v, f'{path}->{k}')
    elif isinstance(d, list) and len(d) > 0:
        find_keys(d[0], f'{path}[0]')

find_keys(data)
"
